import { parse } from 'csv-parse/sync';

// Define the structure of a trip
export interface TripData {
  route_id: string;
  service_id: string;
  trip_id: string;
  trip_headsign: string;
  direction_id: string;
  block_id: string;
  shape_id: string;
  wheelchair_accessible: string;
  bikes_allowed: string;
}

/**
 * Loads trip data from the provided CSV string
 * @returns Promise resolving to an array of TripData objects
 */
export async function loadTripDataFromCsvString(): Promise<TripData[]> {
  try {
	const fileContent = TRIPS;
	
	if (!fileContent || fileContent.trim() === '') {
	  console.error('Empty trips file found');
	  return [];
	}
	
	// Parse CSV data with error handling
	try {
	  const records = parse(fileContent, {
		columns: true,
		skip_empty_lines: true,
		trim: true,
		cast: true
	  });
	  
	  // Validate that we have records with the required fields
	  if (!records || !Array.isArray(records) || records.length === 0) {
		console.error('No valid records found in trips data');
		return [];
	  }
	  
	  // Remove quotes from string values and validate required fields
	  return records.map((trip: any) => {
		// Initialize with all required fields to satisfy TypeScript
		const cleanTrip: TripData = {
		  route_id: '',
		  service_id: '',
		  trip_id: '',
		  trip_headsign: '',
		  direction_id: '',
		  block_id: '',
		  shape_id: '',
		  wheelchair_accessible: '',
		  bikes_allowed: ''
		};
		
		// Process all fields from the record
		Object.keys(trip).forEach(key => {
		  if (key in cleanTrip) { // Only process keys that are in TripData interface
			if (typeof trip[key] === 'string') {
			  (cleanTrip as any)[key] = trip[key].replace(/^"|"$/g, '');
			} else {
			  (cleanTrip as any)[key] = trip[key]?.toString() || '';
			}
		  }
		});
		
		// Set default values for required fields if missing
		if (!cleanTrip.trip_id) cleanTrip.trip_id = 'unknown';
		if (!cleanTrip.route_id) cleanTrip.route_id = 'unknown';
		if (!cleanTrip.service_id) cleanTrip.service_id = 'unknown';
		if (!cleanTrip.trip_headsign) cleanTrip.trip_headsign = 'Unnamed Trip';
		
		return cleanTrip;
	  });
	} catch (parseError) {
	  console.error('Error parsing CSV data:', parseError);
	  return [];
	}
  } catch (error) {
	console.error('Error loading trip data:', error);
	return [];
  }
}

